import { Image } from "react-native";

// Embedded from client/assets/bots/bot-01.png through bot-20.png.
// Data URIs keep the same local assets available in web and native host bundles.
const avatars = [
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
] as const;

// Agent IDs provide a stable pseudo-random assignment across refreshes and hosts.
export function avatarIndex(agentId: string): number {
  let hash = 2166136261;
  for (const char of agentId) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619);
  return (hash >>> 0) % avatars.length;
}

export function AgentAvatar({ agentId, size }: { agentId: string; size: number }) {
  return (
    <Image
      accessible={false}
      source={{ uri: avatars[avatarIndex(agentId)] }}
      style={{ width: size, height: size, borderRadius: size * 0.22, flexShrink: 0 }}
    />
  );
}
